#include "storage_port_fake.h"
#include <string.h>
#include <stdlib.h>

/* ---- Write state ---- */
static storage_result_t s_write_queue[STORAGE_FAKE_MAX_QUEUED_RESULTS];
static size_t s_write_queue_len;
static size_t s_write_queue_pos;
static int s_write_call_count;
static size_t s_total_bytes_written;

/* ---- Read state ---- */
static storage_result_t s_read_queue[STORAGE_FAKE_MAX_QUEUED_RESULTS];
static size_t s_read_queue_len;
static size_t s_read_queue_pos;
static int s_read_call_count;

static uint8_t s_read_data[STORAGE_FAKE_READ_DATA_CAPACITY];
static size_t s_read_data_len;
static size_t s_read_data_pos;

/* ---- Directory listing state ---- */
static storage_dir_entry_t s_dir_entries[STORAGE_FAKE_MAX_DIR_ENTRIES];
static size_t s_dir_entry_count;
static storage_result_t s_listdir_result;

/* ---- Root iterator state ---- */
static bool s_dir_open;                     /* Storage_DirOpen without a close */
static size_t s_dir_pos;                    /* index of the next entry Storage_DirNext reports */
static storage_result_t s_dir_open_result;  /* what Storage_DirOpen returns */
static size_t s_dir_corrupt_at;             /* Storage_DirNext fails here (STORAGE_FAKE_NEVER = never) */
static size_t s_dir_next_calls;             /* Storage_DirNext calls since the reset */

/* ---- In-memory card state ---- */
typedef struct
{
    bool     used;
    bool     is_dir;
    bool     read_only;
    char     path[STORAGE_FAKE_PATH_LEN];
    uint16_t fdate;
    uint16_t ftime;
    uint8_t *data;                          /* malloc'd contents; NULL for a folder or an empty file */
    uint32_t size;                          /* bytes in data */
} fake_item_t;

typedef struct
{
    bool             armed;                 /* a failure is planned for this op */
    uint32_t         calls_left;            /* calls to let through first */
    storage_result_t result;                /* what the failing call returns */
} fake_failure_t;

/* One open file: the read/play file or the effect file. */
typedef struct
{
    bool     open;
    char     path[STORAGE_FAKE_PATH_LEN];   /* the item it reads or writes */
    uint32_t pos;                           /* byte position */
} fake_file_t;

/* One FatFs lock slot. A failed close keeps it (path stays, for FR_LOCKED). */
typedef struct
{
    bool used;
    char path[STORAGE_FAKE_PATH_LEN];
} fake_slot_t;

static fake_item_t    s_items[STORAGE_FAKE_CARD_MAX_ITEMS];
static fake_failure_t s_failures[STORAGE_FAKE_OP_COUNT];
static uint32_t       s_op_calls[STORAGE_FAKE_OP_COUNT];
static bool           s_card_pulled;
static bool           s_card_used;          /* the test put a file on the in-memory card */
static fake_file_t    s_read_file;          /* Storage_OpenRead's file */
static fake_file_t    s_fx_file;            /* Storage_FxCreate's file */
static fake_slot_t    s_slots[STORAGE_FAKE_LOCK_SLOTS];
static uint32_t       s_free_bytes;

void StoragePortFake_Reset(void)
{
    memset(s_write_queue, 0, sizeof(s_write_queue));
    s_write_queue_len = 0U;
    s_write_queue_pos = 0U;
    s_write_call_count = 0;
    s_total_bytes_written = 0U;

    memset(s_read_queue, 0, sizeof(s_read_queue));
    s_read_queue_len = 0U;
    s_read_queue_pos = 0U;
    s_read_call_count = 0;

    memset(s_read_data, 0, sizeof(s_read_data));
    s_read_data_len = 0U;
    s_read_data_pos = 0U;

    memset(s_dir_entries, 0, sizeof(s_dir_entries));
    s_dir_entry_count = 0U;
    s_listdir_result = STORAGE_OK;

    s_dir_open = false;
    s_dir_pos = 0U;
    s_dir_open_result = STORAGE_OK;
    s_dir_corrupt_at = STORAGE_FAKE_NEVER;
    s_dir_next_calls = 0U;

    for (size_t i = 0U; i < STORAGE_FAKE_CARD_MAX_ITEMS; i++)
    {
        free(s_items[i].data);
    }
    memset(s_items, 0, sizeof(s_items));
    memset(s_failures, 0, sizeof(s_failures));
    memset(s_op_calls, 0, sizeof(s_op_calls));
    s_card_pulled = false;
    s_card_used = false;
    memset(&s_read_file, 0, sizeof(s_read_file));
    memset(&s_fx_file, 0, sizeof(s_fx_file));
    memset(s_slots, 0, sizeof(s_slots));
    s_free_bytes = STORAGE_FAKE_DEFAULT_FREE;
}

void StoragePortFake_QueueWriteResult(storage_result_t result)
{
    if (s_write_queue_len < STORAGE_FAKE_MAX_QUEUED_RESULTS)
    {
        s_write_queue[s_write_queue_len] = result;
        s_write_queue_len++;
    }
}

int StoragePortFake_GetWriteCallCount(void)
{
    return s_write_call_count;
}

size_t StoragePortFake_GetTotalBytesWritten(void)
{
    return s_total_bytes_written;
}

void StoragePortFake_QueueReadResult(storage_result_t result)
{
    if (s_read_queue_len < STORAGE_FAKE_MAX_QUEUED_RESULTS)
    {
        s_read_queue[s_read_queue_len] = result;
        s_read_queue_len++;
    }
}

void StoragePortFake_SetReadData(const uint8_t *data, size_t len)
{
    if (len > STORAGE_FAKE_READ_DATA_CAPACITY)
    {
        len = STORAGE_FAKE_READ_DATA_CAPACITY;
    }
    memcpy(s_read_data, data, len);
    s_read_data_len = len;
    s_read_data_pos = 0U;
}

int StoragePortFake_GetReadCallCount(void)
{
    return s_read_call_count;
}

void StoragePortFake_SetDirEntries(const storage_dir_entry_t *entries, size_t count)
{
    if (count > STORAGE_FAKE_MAX_DIR_ENTRIES)
    {
        count = STORAGE_FAKE_MAX_DIR_ENTRIES;
    }
    memcpy(s_dir_entries, entries, count * sizeof(storage_dir_entry_t));
    s_dir_entry_count = count;
}

void StoragePortFake_SetListDirResult(storage_result_t result)
{
    s_listdir_result = result;
}

void StoragePortFake_SetDirOpenResult(storage_result_t result)
{
    s_dir_open_result = result;
}

void StoragePortFake_SetDirCorruptAt(size_t index)
{
    s_dir_corrupt_at = index;
}

size_t StoragePortFake_GetDirNextCallCount(void)
{
    return s_dir_next_calls;
}

bool StoragePortFake_IsDirOpen(void)
{
    return s_dir_open;
}

/* ==================== storage_port.h implementation ==================== */

storage_result_t Storage_WriteChunk(const uint8_t *data, size_t len)
{
    (void)data;
    s_write_call_count++;

    storage_result_t result = STORAGE_OK;
    if (s_write_queue_len > 0U)
    {
        if (s_write_queue_pos < s_write_queue_len)
        {
            result = s_write_queue[s_write_queue_pos];
            s_write_queue_pos++;
        }
        else
        {
            /* Queue exhausted - repeat the last queued result ("sticky"). */
            result = s_write_queue[s_write_queue_len - 1U];
        }
    }

    if (result == STORAGE_OK || result == STORAGE_SLOW)
    {
        s_total_bytes_written += len;
    }

    return result;
}

static storage_result_t card_read(uint8_t *out, size_t max_len, size_t *out_read);

storage_result_t Storage_ReadChunk(uint8_t *out, size_t max_len, size_t *out_read)
{
    if (s_read_file.open)
    {
        return card_read(out, max_len, out_read);   /* the in-memory card's read/play file */
    }
    if (s_card_used)
    {
        *out_read = 0U;
        return STORAGE_READ_FAIL;                   /* no file open: the real port (jack_ports.c) fails too */
    }
    s_read_call_count++;

    storage_result_t result = STORAGE_OK;
    if (s_read_queue_len > 0U)
    {
        if (s_read_queue_pos < s_read_queue_len)
        {
            result = s_read_queue[s_read_queue_pos];
            s_read_queue_pos++;
        }
        else
        {
            result = s_read_queue[s_read_queue_len - 1U];
        }
    }

    if (result != STORAGE_OK)
    {
        *out_read = 0U;
        return result;
    }

    size_t available = s_read_data_len - s_read_data_pos;
    size_t to_copy = (max_len < available) ? max_len : available;

    memcpy(out, &s_read_data[s_read_data_pos], to_copy);
    s_read_data_pos += to_copy;
    *out_read = to_copy;

    return STORAGE_OK;
}

storage_result_t Storage_ListDir(storage_dir_entry_t *out, size_t max_entries, size_t *out_count)
{
    size_t to_copy = (max_entries < s_dir_entry_count) ? max_entries : s_dir_entry_count;
    memcpy(out, s_dir_entries, to_copy * sizeof(storage_dir_entry_t));
    *out_count = to_copy;

    if (s_listdir_result != STORAGE_OK)
    {
        return s_listdir_result;
    }
    if (s_dir_entry_count > max_entries)
    {
        return STORAGE_TRUNCATED;
    }
    return STORAGE_OK;
}

/* The root iterator walks the same entries as Storage_ListDir, one per call.
 * Every fake entry is a regular file (the real port skips folders). */
storage_result_t Storage_DirOpen(void)
{
    s_dir_pos = 0U;
    if (s_dir_open_result != STORAGE_OK)
    {
        s_dir_open = false;
        return s_dir_open_result;
    }
    s_dir_open = true;
    return STORAGE_OK;
}

storage_result_t Storage_DirNext(storage_dir_entry_t *entry)
{
    s_dir_next_calls++;
    if (!s_dir_open || (entry == NULL))
    {
        return STORAGE_CORRUPT;
    }
    if (s_dir_pos == s_dir_corrupt_at)
    {
        return STORAGE_CORRUPT;
    }
    if (s_dir_pos >= s_dir_entry_count)
    {
        return STORAGE_NOT_FOUND;
    }
    *entry = s_dir_entries[s_dir_pos];
    s_dir_pos++;
    return STORAGE_OK;
}

void Storage_DirClose(void)
{
    s_dir_open = false;
}

/* ==================== the in-memory card (group 3) ==================== */

static fake_item_t *find_item(const char *path)
{
    if (path == NULL)
    {
        return NULL;
    }
    for (size_t i = 0U; i < STORAGE_FAKE_CARD_MAX_ITEMS; i++)
    {
        if (s_items[i].used && strncmp(s_items[i].path, path, STORAGE_FAKE_PATH_LEN) == 0)
        {
            return &s_items[i];
        }
    }
    return NULL;
}

static fake_item_t *new_item(const char *path)
{
    if (path == NULL || strlen(path) >= STORAGE_FAKE_PATH_LEN)
    {
        return NULL;
    }
    for (size_t i = 0U; i < STORAGE_FAKE_CARD_MAX_ITEMS; i++)
    {
        if (!s_items[i].used)
        {
            memset(&s_items[i], 0, sizeof(s_items[i]));
            s_items[i].used = true;
            strncpy(s_items[i].path, path, STORAGE_FAKE_PATH_LEN - 1U);
            return &s_items[i];
        }
    }
    return NULL;
}

static void remove_item(fake_item_t *item)
{
    free(item->data);
    memset(item, 0, sizeof(*item));
}

/* True when a folder holds anything: another item's path starts with
 * "<folder>/". */
static bool folder_has_items(const fake_item_t *folder)
{
    const size_t len = strlen(folder->path);
    for (size_t i = 0U; i < STORAGE_FAKE_CARD_MAX_ITEMS; i++)
    {
        const fake_item_t *other = &s_items[i];
        if (other->used && other != folder &&
            strncmp(other->path, folder->path, len) == 0 && other->path[len] == '/')
        {
            return true;
        }
    }
    return false;
}

/* Count the call, and return the planned failure for it, if any (else OK). */
static storage_result_t take_planned_result(storage_fake_op_t op)
{
    s_op_calls[op]++;
    fake_failure_t *f = &s_failures[op];
    if (!f->armed)
    {
        return STORAGE_OK;
    }
    if (f->calls_left > 0U)
    {
        f->calls_left--;
        return STORAGE_OK;
    }
    f->armed = false;
    return f->result;
}

bool StoragePortFake_CardAddFile(const char *path, const uint8_t *data, uint32_t size)
{
    s_card_used = true;
    fake_item_t *item = find_item(path);
    if (item != NULL)
    {
        remove_item(item);
    }
    item = new_item(path);
    if (item == NULL)
    {
        return false;
    }
    if (size > 0U)
    {
        item->data = (uint8_t *)calloc(size, 1U);
        if (item->data == NULL)
        {
            remove_item(item);
            return false;
        }
        if (data != NULL)
        {
            memcpy(item->data, data, size);
        }
    }
    item->size = size;
    return true;
}

bool StoragePortFake_CardAddDir(const char *path)
{
    if (find_item(path) != NULL)
    {
        return true;
    }
    fake_item_t *item = new_item(path);
    if (item == NULL)
    {
        return false;
    }
    item->is_dir = true;
    return true;
}

void StoragePortFake_CardSetTime(const char *path, uint16_t fdate, uint16_t ftime)
{
    fake_item_t *item = find_item(path);
    if (item != NULL)
    {
        item->fdate = fdate;
        item->ftime = ftime;
    }
}

void StoragePortFake_CardSetReadOnly(const char *path, bool read_only)
{
    fake_item_t *item = find_item(path);
    if (item != NULL)
    {
        item->read_only = read_only;
    }
}

bool StoragePortFake_CardExists(const char *path)
{
    return find_item(path) != NULL;
}

bool StoragePortFake_CardIsDir(const char *path)
{
    const fake_item_t *item = find_item(path);
    return (item != NULL) && item->is_dir;
}

uint32_t StoragePortFake_CardFileSize(const char *path)
{
    const fake_item_t *item = find_item(path);
    return (item != NULL) ? item->size : 0U;
}

void StoragePortFake_CardFailOp(storage_fake_op_t op, uint32_t after_calls, storage_result_t result)
{
    if (op >= STORAGE_FAKE_OP_COUNT)
    {
        return;
    }
    s_failures[op].armed = true;
    s_failures[op].calls_left = after_calls;
    s_failures[op].result = result;
}

void StoragePortFake_CardPull(bool pulled)
{
    s_card_pulled = pulled;
}

uint32_t StoragePortFake_GetOpCallCount(storage_fake_op_t op)
{
    return (op < STORAGE_FAKE_OP_COUNT) ? s_op_calls[op] : 0U;
}

/* ---- lock slots ---- */

static bool take_slot(const char *path)
{
    for (size_t i = 0U; i < STORAGE_FAKE_LOCK_SLOTS; i++)
    {
        if (!s_slots[i].used)
        {
            s_slots[i].used = true;
            strncpy(s_slots[i].path, path, STORAGE_FAKE_PATH_LEN - 1U);
            s_slots[i].path[STORAGE_FAKE_PATH_LEN - 1U] = '\0';
            return true;
        }
    }
    return false;                               /* FR_TOO_MANY_OPEN_FILES */
}

static void free_slot(const char *path)
{
    for (size_t i = 0U; i < STORAGE_FAKE_LOCK_SLOTS; i++)
    {
        if (s_slots[i].used && strncmp(s_slots[i].path, path, STORAGE_FAKE_PATH_LEN) == 0)
        {
            memset(&s_slots[i], 0, sizeof(s_slots[i]));
            return;
        }
    }
}

/* A path with a slot (open, or kept by a failed close): FatFs says FR_LOCKED. */
static bool path_locked(const char *path)
{
    for (size_t i = 0U; i < STORAGE_FAKE_LOCK_SLOTS; i++)
    {
        if (s_slots[i].used && strncmp(s_slots[i].path, path, STORAGE_FAKE_PATH_LEN) == 0)
        {
            return true;
        }
    }
    return false;
}

/* The folder part of a path ("FX/ECHO" of "FX/ECHO/A.WAV"); "" for the root. */
static void parent_of(const char *path, char *out)
{
    strncpy(out, path, STORAGE_FAKE_PATH_LEN - 1U);
    out[STORAGE_FAKE_PATH_LEN - 1U] = '\0';
    char *slash = strrchr(out, '/');
    if (slash == NULL)
    {
        out[0] = '\0';
        return;
    }
    *slash = '\0';
}

/* True when the folder a path lies in exists (the root always does). */
static bool parent_is_folder(const char *path)
{
    char parent[STORAGE_FAKE_PATH_LEN];
    parent_of(path, parent);
    if (parent[0] == '\0')
    {
        return true;
    }
    const fake_item_t *folder = find_item(parent);
    return (folder != NULL) && folder->is_dir;
}

/* Close one open file. A failure (planned, or a pulled card) keeps its slot. */
static storage_result_t close_file(fake_file_t *file, storage_fake_op_t op)
{
    const storage_result_t planned = take_planned_result(op);
    if (!file->open)
    {
        return STORAGE_OK;
    }
    file->open = false;
    if (s_card_pulled)
    {
        return STORAGE_WRITE_FAIL;              /* the slot stays used, as in FatFs */
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    free_slot(file->path);
    return STORAGE_OK;
}

const uint8_t *StoragePortFake_CardFileData(const char *path)
{
    const fake_item_t *item = find_item(path);
    return (item != NULL) ? item->data : NULL;
}

void StoragePortFake_CardSetFreeBytes(uint32_t free_bytes)
{
    s_free_bytes = free_bytes;
}

uint32_t StoragePortFake_CardFreeBytes(void)
{
    return s_free_bytes;
}

uint32_t StoragePortFake_CardSlotsInUse(void)
{
    uint32_t used = 0U;
    for (size_t i = 0U; i < STORAGE_FAKE_LOCK_SLOTS; i++)
    {
        if (s_slots[i].used)
        {
            used++;
        }
    }
    return used;
}

bool StoragePortFake_CardReadFileOpen(void)
{
    return s_read_file.open;
}

bool StoragePortFake_CardFxFileOpen(void)
{
    return s_fx_file.open;
}

void StoragePortFake_CardRemount(void)
{
    memset(&s_read_file, 0, sizeof(s_read_file));
    memset(&s_fx_file, 0, sizeof(s_fx_file));
    memset(s_slots, 0, sizeof(s_slots));
}

/* ==================== storage_port.h group 3 ==================== */

storage_result_t Storage_Stat(const char *path, storage_stat_t *st)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_STAT);
    if (path == NULL || st == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    if (s_card_pulled)
    {
        return STORAGE_READ_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    const fake_item_t *item = find_item(path);
    if (item == NULL)
    {
        return STORAGE_NOT_FOUND;
    }
    st->size = item->is_dir ? 0U : item->size;
    st->fdate = item->fdate;
    st->ftime = item->ftime;
    st->is_dir = item->is_dir ? 1U : 0U;
    return STORAGE_OK;
}

storage_result_t Storage_Unlink(const char *path)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_UNLINK);
    if (path == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    if (s_card_pulled)
    {
        return STORAGE_WRITE_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    fake_item_t *item = find_item(path);
    if (item == NULL)
    {
        return STORAGE_NOT_FOUND;
    }
    if (item->read_only || path_locked(path) || (item->is_dir && folder_has_items(item)))
    {
        return STORAGE_REFUSED;                 /* FR_DENIED / FR_LOCKED */
    }
    s_free_bytes += item->size;
    remove_item(item);
    return STORAGE_OK;
}

storage_result_t Storage_OpenRead(const char *path)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_OPEN_READ);
    if (path == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    if (s_read_file.open && !s_card_pulled)
    {
        s_read_file.open = false;               /* the old read/play file is closed first */
        free_slot(s_read_file.path);
    }
    s_read_file.open = false;
    if (s_card_pulled)
    {
        return STORAGE_READ_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    const fake_item_t *item = find_item(path);
    if (item == NULL || item->is_dir)
    {
        return STORAGE_NOT_FOUND;
    }
    if (s_fx_file.open && strncmp(s_fx_file.path, path, STORAGE_FAKE_PATH_LEN) == 0)
    {
        return STORAGE_REFUSED;                 /* open for writing: FR_LOCKED */
    }
    if (!take_slot(path))
    {
        return STORAGE_NO_SLOT;
    }
    s_read_file.open = true;
    strncpy(s_read_file.path, path, STORAGE_FAKE_PATH_LEN - 1U);
    s_read_file.path[STORAGE_FAKE_PATH_LEN - 1U] = '\0';
    s_read_file.pos = 0U;
    return STORAGE_OK;
}

static storage_result_t card_read(uint8_t *out, size_t max_len, size_t *out_read)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_READ);
    if (out == NULL || out_read == NULL || max_len == 0U)
    {
        return STORAGE_INVALID_ARG;
    }
    *out_read = 0U;
    if (s_card_pulled)
    {
        return STORAGE_READ_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    const fake_item_t *item = find_item(s_read_file.path);
    if (item == NULL)
    {
        return STORAGE_READ_FAIL;
    }
    const uint32_t left = (s_read_file.pos < item->size) ? (item->size - s_read_file.pos) : 0U;
    const size_t n = (max_len < left) ? max_len : left;
    if (n > 0U)
    {
        memcpy(out, &item->data[s_read_file.pos], n);
    }
    s_read_file.pos += (uint32_t)n;
    *out_read = n;
    return STORAGE_OK;
}

storage_result_t Storage_Seek(uint32_t offset)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_SEEK);
    if (!s_read_file.open)
    {
        return STORAGE_INVALID_ARG;
    }
    if (s_card_pulled)
    {
        return STORAGE_READ_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    const fake_item_t *item = find_item(s_read_file.path);
    const uint32_t size = (item != NULL) ? item->size : 0U;
    s_read_file.pos = (offset < size) ? offset : size;     /* a read-only file cannot grow */
    return STORAGE_OK;
}

storage_result_t Storage_Close(void)
{
    return close_file(&s_read_file, STORAGE_FAKE_OP_CLOSE);
}

storage_result_t Storage_FxCreate(const char *path)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_FX_CREATE);
    if (path == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    if (s_card_pulled)
    {
        return STORAGE_WRITE_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    if (!parent_is_folder(path))
    {
        return STORAGE_NOT_FOUND;               /* FR_NO_PATH */
    }
    if (find_item(path) != NULL)
    {
        return STORAGE_REFUSED;                 /* FA_CREATE_NEW: FR_EXIST */
    }
    if (!take_slot(path))
    {
        return STORAGE_NO_SLOT;
    }
    if (!StoragePortFake_CardAddFile(path, NULL, 0U))
    {
        free_slot(path);
        return STORAGE_REFUSED;
    }
    s_fx_file.open = true;
    strncpy(s_fx_file.path, path, STORAGE_FAKE_PATH_LEN - 1U);
    s_fx_file.path[STORAGE_FAKE_PATH_LEN - 1U] = '\0';
    s_fx_file.pos = 0U;
    return STORAGE_OK;
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): a parked job's .TMP opened
 * again, in the board's order of checks. */
storage_result_t Storage_FxOpenExisting(const char *path, uint32_t *size)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_FX_OPEN);
    if (path == NULL || size == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    if (s_fx_file.open)
    {
        (void)Storage_FxClose();                /* as the board: an effect file still open is closed first */
    }
    if (s_card_pulled)
    {
        return STORAGE_READ_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    const fake_item_t *item = find_item(path);
    if (item == NULL || item->is_dir)
    {
        return STORAGE_NOT_FOUND;
    }
    if (item->read_only || path_locked(path))
    {
        return STORAGE_REFUSED;                 /* FR_DENIED / FR_LOCKED */
    }
    if (!take_slot(path))
    {
        return STORAGE_NO_SLOT;
    }
    s_fx_file.open = true;
    strncpy(s_fx_file.path, path, STORAGE_FAKE_PATH_LEN - 1U);
    s_fx_file.path[STORAGE_FAKE_PATH_LEN - 1U] = '\0';
    s_fx_file.pos = 0U;
    *size = item->size;
    return STORAGE_OK;
}

/* Make the file at least new_size bytes long, using up free space. Returns
 * the size it could reach (less than new_size when the card is full). */
static uint32_t grow_item(fake_item_t *item, uint32_t new_size)
{
    if (new_size <= item->size)
    {
        return new_size;
    }
    uint32_t extra = new_size - item->size;
    if (extra > s_free_bytes)
    {
        extra = s_free_bytes;
    }
    const uint32_t reached = item->size + extra;
    uint8_t *grown = (uint8_t *)realloc(item->data, (reached > 0U) ? reached : 1U);
    if (grown == NULL)
    {
        return item->size;
    }
    memset(&grown[item->size], 0, extra);
    item->data = grown;
    item->size = reached;
    s_free_bytes -= extra;
    return reached;
}

storage_result_t Storage_FxWrite(const uint8_t *data, size_t len)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_FX_WRITE);
    if (data == NULL || len == 0U)
    {
        return STORAGE_INVALID_ARG;
    }
    if (!s_fx_file.open)
    {
        return STORAGE_REFUSED;
    }
    if (s_card_pulled)
    {
        return STORAGE_WRITE_FAIL;
    }
    if (planned != STORAGE_OK && planned != STORAGE_SLOW)
    {
        return planned;
    }
    fake_item_t *item = find_item(s_fx_file.path);
    if (item == NULL)
    {
        return STORAGE_WRITE_FAIL;
    }
    if (planned == STORAGE_SLOW)
    {
        /* A planned SLOW still writes everything: it stands for a write that
         * completed, but late (the real Storage_FxWrite never says SLOW). */
        const uint32_t slow_end = s_fx_file.pos + (uint32_t)len;
        if (grow_item(item, slow_end) < slow_end)
        {
            return STORAGE_FULL;
        }
        memcpy(&item->data[s_fx_file.pos], data, len);
        s_fx_file.pos = slow_end;
        return STORAGE_SLOW;
    }
    const uint32_t end = s_fx_file.pos + (uint32_t)len;
    const uint32_t reached = grow_item(item, end);
    const uint32_t n = (reached > s_fx_file.pos) ? (reached - s_fx_file.pos) : 0U;
    if (n > 0U)
    {
        memcpy(&item->data[s_fx_file.pos], data, n);
    }
    s_fx_file.pos += n;
    return (n < len) ? STORAGE_FULL : STORAGE_OK;    /* a short write: the card is full */
}

storage_result_t Storage_FxSeek(uint32_t offset)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_FX_SEEK);
    if (!s_fx_file.open)
    {
        return STORAGE_REFUSED;
    }
    if (s_card_pulled)
    {
        return STORAGE_WRITE_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    const fake_item_t *item = find_item(s_fx_file.path);
    const uint32_t size = (item != NULL) ? item->size : 0U;
    if (offset > size)
    {
        return STORAGE_INVALID_ARG;             /* the board's rule: never past the end */
    }
    s_fx_file.pos = offset;
    return STORAGE_OK;
}

storage_result_t Storage_FxSync(void)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_FX_SYNC);
    if (!s_fx_file.open)
    {
        return STORAGE_REFUSED;
    }
    if (s_card_pulled)
    {
        return STORAGE_WRITE_FAIL;
    }
    return planned;
}

storage_result_t Storage_FxClose(void)
{
    return close_file(&s_fx_file, STORAGE_FAKE_OP_FX_CLOSE);
}

storage_result_t Storage_Mkdir(const char *path)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_MKDIR);
    if (path == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    if (s_card_pulled)
    {
        return STORAGE_WRITE_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    const fake_item_t *item = find_item(path);
    if (item != NULL)
    {
        return item->is_dir ? STORAGE_OK : STORAGE_REFUSED;   /* a FILE of that name */
    }
    if (!parent_is_folder(path))
    {
        return STORAGE_REFUSED;                 /* FR_NO_PATH: a path through a file or a missing folder */
    }
    if (s_free_bytes == 0U)
    {
        return STORAGE_FULL;                    /* no free cluster for the new folder (FR_DENIED) */
    }
    return StoragePortFake_CardAddDir(path) ? STORAGE_OK : STORAGE_REFUSED;
}

storage_result_t Storage_Rename(const char *from, const char *to)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_RENAME);
    if (from == NULL || to == NULL || strlen(to) >= STORAGE_FAKE_PATH_LEN)
    {
        return STORAGE_INVALID_ARG;
    }
    if (s_card_pulled)
    {
        return STORAGE_WRITE_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    fake_item_t *item = find_item(from);
    if (item == NULL)
    {
        return STORAGE_NOT_FOUND;
    }
    if (find_item(to) != NULL || path_locked(from))
    {
        return STORAGE_REFUSED;                 /* FR_EXIST / FR_LOCKED */
    }
    memset(item->path, 0, sizeof(item->path));
    strncpy(item->path, to, STORAGE_FAKE_PATH_LEN - 1U);
    return STORAGE_OK;
}

storage_result_t Storage_FreeKb(uint32_t *free_kb)
{
    const storage_result_t planned = take_planned_result(STORAGE_FAKE_OP_FREE_KB);
    if (free_kb == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    if (s_card_pulled)
    {
        return STORAGE_READ_FAIL;
    }
    if (planned != STORAGE_OK)
    {
        return planned;
    }
    *free_kb = s_free_bytes / 1024U;
    return STORAGE_OK;
}
